 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    # Motifs are 2x2 squares (color 1) and L triominoes. The color of an L
    # identifies which corner is absent.
    missing_color = {(0, 0): 2, (0, 1): 4, (1, 0): 3, (1, 1): 5}
    pieces = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if square <= occupied:
                pieces.append((square, 1))
            for (dr, dc), color in missing_color.items():
                tri = square - {(r + dr, c + dc)}
                if tri <= occupied:
                    pieces.append((tri, color))
    by_cell = {p: [] for p in occupied}
    for piece in pieces:
        for p in piece[0]:
            by_cell[p].append(piece)

    def tile(remaining):
        if not remaining:
            return []
        # Most constrained cell first gives a small exact-cover search.
        cell = min(remaining, key=lambda p: sum(s <= remaining for s, _ in by_cell[p]))
        for shape, color in by_cell[cell]:
            if shape <= remaining:
                rest = tile(remaining - shape)
                if rest is not None:
                    return [(shape, color)] + rest
        return None

    solution = tile(occupied)
    out = [[0] * w for _ in range(h)]
    if solution is None:
        return out
    for shape, color in solution:
        for r, c in shape:
            out[r][c] = color
    return out

if __name__ == '__main__':
